import math


def bags_needed(kg, bag_size=90):
    """Bags needed for kg. A part-full bag still needs a bag. Negative kg raises ValueError."""
    if kg < 0:
        raise ValueError("kg can't be negative")
    return math.ceil(kg / bag_size)


def test_whole_bags():
    assert bags_needed(180) == 2


def test_part_bag():
    assert bags_needed(100) == 2     # 1.1 bags: rounding to nearest would say 1
    assert bags_needed(250) == 3


def test_other_bag_size():
    assert bags_needed(101, bag_size=50) == 3


def test_zero():
    assert bags_needed(0) == 0


def test_negative_is_refused():
    try:
        bags_needed(-5)
    except ValueError:
        return
    raise AssertionError("bags_needed(-5) should raise ValueError")

