exercises.solution:
def clean_name(text):
    words = text.split()        # split() with no argument drops all extra spaces
    return " ".join(w.capitalize() for w in words)


def initials(text):
    return "".join(w[0] for w in clean_name(text).split())


# ---- the tests (given). Make them pass, then add one more test of your own. ----

def test_strips_and_capitalises():
    assert clean_name("  amina  ") == "Amina"


def test_collapses_spaces():
    assert clean_name("amina    wanjiru") == "Amina Wanjiru"


def test_rest_lowercase():
    assert clean_name("JUMA oTIENO") == "Juma Otieno"


def test_initials():
    assert initials(" amina   wanjiru ") == "AW"


def test_blank_gives_empty():
    assert clean_name("   ") == ""
    assert initials("") == ""

